package com.example.product;

import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.reactive.function.client.WebClient;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

@RestController
public class ProductController {
    private final ProductRepository productRepository;
    private final WebClient inventoryClient;

    public ProductController(ProductRepository productRepository, WebClient inventoryClient) {
        this.productRepository = productRepository;
        this.inventoryClient = inventoryClient;
    }

    @GetMapping("/products/{id}")
    public Mono<ProductView> get(@PathVariable long id) {
        Product product = productRepository.findById(id).orElseThrow(() -> new ProductNotFoundException(id));
        Integer stock = inventoryClient.get()
                .uri("/stock/{id}", id)
                .retrieve()
                .bodyToMono(Integer.class)
                .block();
        return Mono.just(new ProductView(product.getId(), product.getName(), stock));
    }

    @GetMapping("/products")
    public Flux<ProductSummary> list() {
        return Flux.fromIterable(productRepository.findAll())
                .map(p -> new ProductSummary(p.getId(), p.getName()));
    }
}

