import reactor.core.scheduler.Schedulers;

@GetMapping("/products/{id}")
public Mono<ProductView> get(@PathVariable long id) {
    Mono<Product> product = Mono.just(productRepository.findById(id).orElseThrow(() -> new ProductNotFoundException(id)))
            .subscribeOn(Schedulers.boundedElastic());
    Mono<Integer> stock = inventoryClient.get()
            .uri("/stock/{id}", id)
            .retrieve()
            .bodyToMono(Integer.class);
    return Mono.zip(product, stock, (p, s) -> new ProductView(p.getId(), p.getName(), s));
}

@GetMapping("/products")
public Flux<ProductSummary> list() {
    return Flux.defer(() -> Flux.fromIterable(productRepository.findAll()))
            .subscribeOn(Schedulers.boundedElastic())
            .map(p -> new ProductSummary(p.getId(), p.getName()));
}
